      ticks.push({ label: String(x), style: 'position: absolute; left: ' + Math.round((x - lo) / span * W) + 'px; top: 0; width: 0; height: 100%', tick: 'position: absolute; left: -1px; top: 26px; width: 3px; height: ' + (big ? 22 : 12) + 'px; background: ' + (hl ? '#FFC83D' : '#C9C3F2'), lab: 'position: absolute; top: 54px; left: -20px; width: 40px; text-align: center; font-size: ' + (span <= 20 ? 16 : 18) + 'px; font-weight: ' + (hl ? 700 : 500) + '; color: ' + (hl ? '#FFC83D' : '#E6E1FF') });
